package tw.com.tft.documentscanner.imaging;import android.graphics.*;import androidx.exifinterface.media.ExifInterface;import java.io.File;public final class ImageLoader{public static Bitmap loadPreview(String p,int max)throws Exception{BitmapFactory.Options b=new BitmapFactory.Options();b.inJustDecodeBounds=true;BitmapFactory.decodeFile(p,b);if(b.outWidth<=0)throw new IllegalArgumentException("decode");int s=1,l=Math.max(b.outWidth,b.outHeight);while(l/s>max*1.35)s*=2;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=s;o.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap d=BitmapFactory.decodeFile(p,o);if(d==null)throw new IllegalArgumentException("decode");Bitmap r=exif(d,p);if(r!=d)d.recycle();int m=Math.max(r.getWidth(),r.getHeight());if(m<=max)return r;float sc=max/(float)m;Bitmap q=Bitmap.createScaledBitmap(r,Math.round(r.getWidth()*sc),Math.round(r.getHeight()*sc),true);if(q!=r)r.recycle();return q;}private static Bitmap exif(Bitmap s,String p)throws Exception{int o=new ExifInterface(new File(p)).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);Matrix m=new Matrix();switch(o){case ExifInterface.ORIENTATION_FLIP_HORIZONTAL:m.setScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_180:m.setRotate(180);break;case ExifInterface.ORIENTATION_FLIP_VERTICAL:m.setScale(1,-1);break;case ExifInterface.ORIENTATION_ROTATE_90:m.setRotate(90);break;case ExifInterface.ORIENTATION_ROTATE_270:m.setRotate(-90);break;default:return s;}return Bitmap.createBitmap(s,0,0,s.getWidth(),s.getHeight(),m,true);}}